import React, { useMemo } from 'react';
import {
  CalendarDays,
  Heart,
  Home,
  LayoutGrid,
  MessageCircle,
  MessageSquareText,
  Plus,
  Trophy,
  UserRound,
  Dumbbell,
  Flame,
  Star,
} from 'lucide-react';
import { useNavigate, useSearchParams } from 'react-router-dom';

function cx(...classes) {
  return classes.filter(Boolean).join(' ');
}

function NavItem({ active, icon: Icon, label, onClick }) {
  return (
    <button
      type="button"
      onClick={onClick}
      className={cx(
        'group inline-flex items-center gap-2 rounded-lg px-3 py-2 text-[13px] font-medium transition',
        active ? 'text-[#ff7849]' : 'text-white/65 hover:text-white/90'
      )}
      aria-current={active ? 'page' : undefined}
    >
      <Icon className={cx('h-4 w-4', active ? 'text-[#ff7849]' : 'text-white/55 group-hover:text-white/80')} />
      {label}
    </button>
  );
}

function Card({ children, className }) {
  return (
    <section
      className={cx(
        'rounded-xl border border-white/10 bg-white/[0.06] shadow-[0_10px_40px_-30px_rgba(0,0,0,0.8)]',
        className
      )}
    >
      {children}
    </section>
  );
}

function CardTitle({ children }) {
  return (
    <div className="px-5 pt-5">
      <h2 className="text-[18px] font-semibold tracking-wide text-white/90" style={{ fontFamily: 'Arimo, Poppins, system-ui' }}>
        {children}
      </h2>
    </div>
  );
}

function PlusEmpty({ label }) {
  return (
    <div className="flex h-full min-h-[220px] items-center justify-center">
      <button
        type="button"
        className="group inline-flex flex-col items-center gap-3"
        aria-label={label}
      >
        <span className="grid h-12 w-12 place-items-center rounded-full border border-white/20 text-white/70 transition group-hover:border-white/30 group-hover:text-white/90">
          <Plus className="h-5 w-5" />
        </span>
      </button>
    </div>
  );
}

function Chip({ children }) {
  return (
    <span className="inline-flex items-center rounded-md bg-[#ff7849]/15 px-2 py-1 text-[11px] font-medium text-[#ff7849]">
      {children}
    </span>
  );
}

function ExerciseRow({ name, series, reps }) {
  return (
    <div className="rounded-lg border border-white/10 bg-white/[0.06] px-4 py-3">
      <div className="text-[13px] font-semibold text-white/85">{name}</div>
      <div className="mt-2 flex gap-2">
        <span className="rounded-md bg-black/30 px-2 py-1 text-[10px] text-white/45">
          {series} SERIES
        </span>
        <span className="rounded-md bg-black/30 px-2 py-1 text-[10px] text-white/45">
          {reps} REPS
        </span>
      </div>
    </div>
  );
}

function AchievementRow({ icon: Icon, title, subtitle, meta }) {
  return (
    <div className="flex items-center gap-4 rounded-lg border border-white/10 bg-white/[0.06] px-4 py-4">
      <div className="grid h-11 w-11 place-items-center rounded-lg border border-[#ff7849]/70 text-[#ff7849]">
        <Icon className="h-5 w-5" />
      </div>
      <div className="min-w-0">
        <div className="text-[12px] font-semibold uppercase tracking-wide text-white/75">{title}</div>
        <div className="mt-0.5 truncate text-[13px] font-semibold text-white/90">{subtitle}</div>
        <div className="mt-1 text-[11px] text-white/45">{meta}</div>
      </div>
    </div>
  );
}

function FitgramPost({ username, likes }) {
  return (
    <div className="overflow-hidden rounded-xl border border-white/10 bg-white/[0.06]">
      <div className="flex items-center gap-3 border-b border-white/10 px-4 py-3">
        <div className="h-5 w-5 rounded-full border-2 border-[#ff7849] opacity-90" />
        <div className="text-[13px] font-semibold text-white/85">@{username}</div>
      </div>

      <div className="relative aspect-[4/3] bg-gradient-to-br from-[#ff7849]/25 via-white/5 to-black/10">
        <div className="absolute inset-0 grid place-items-center">
          <Dumbbell className="h-10 w-10 text-white/15" />
        </div>
        <div className="absolute inset-0 bg-black/10" />
      </div>

      <div className="flex items-center gap-3 px-4 py-3 text-white/55">
        <Heart className="h-4 w-4" />
        <MessageCircle className="h-4 w-4" />
        <div className="ml-auto text-[12px] text-white/60">{likes} me gusta</div>
      </div>
    </div>
  );
}

export default function Main() {
  const navigate = useNavigate();
  const [params] = useSearchParams();
  const demo = params.get('demo') === '1';

  const weekly = useMemo(() => {
    const today = new Date();
    const dayOfWeek = today.getDay();
    // Ajustar para que lunes sea 0 (getDay devuelve 0 para domingo)
    const dayIndex = dayOfWeek === 0 ? 6 : dayOfWeek - 1;

    // Calcular el lunes de esta semana
    const monday = new Date(today);
    monday.setDate(today.getDate() - dayIndex);

    const days = ['LUN', 'MAR', 'MIE', 'JUE', 'VIE', 'SAB', 'DOM'];
    const weekDays = [];

    for (let i = 0; i < 7; i++) {
      const date = new Date(monday);
      date.setDate(monday.getDate() + i);
      const dateNum = date.getDate();

      weekDays.push({
        label: days[i],
        date: dateNum,
        dayIndex: i,
        isToday: i === dayIndex,
        items: demo && i <= dayIndex ? (i === 0 ? ['Rutina Pecho', 'Cardio'] : i === 1 ? ['Rutina Espalda'] : i === 2 ? ['Rutina Pierna'] : i === 3 ? ['Rutina Brazo'] : []) : []
      });
    }

    return weekDays;
  }, [demo]);

  const todayExercises = useMemo(() => {
    if (!demo) return [];
    return [
      { name: 'Sentadillas', series: 3, reps: 12 },
      { name: 'Press de Banca', series: 4, reps: 8 },
      { name: 'Peso muerto', series: 3, reps: 15 },
      { name: 'Hip Trust', series: 4, reps: 10 },
    ];
  }, [demo]);

  const achievements = useMemo(() => {
    if (!demo) return [];
    return [
      { icon: Trophy, title: '7 DÍAS', subtitle: 'CONSECUTIVOS', meta: 'Completado el 15/01' },
      { icon: Dumbbell, title: '50', subtitle: 'Entrenamientos', meta: 'Completado el 10/01' },
      { icon: Star, title: 'Primer Mes', subtitle: 'Completo', meta: 'Completado el 31/12' },
      { icon: Flame, title: 'Racha de 30', subtitle: 'Días', meta: 'En progreso 21 / 30' },
    ];
  }, [demo]);

  const fitgram = useMemo(() => {
    if (!demo) return [];
    return [
      { username: 'usuario1', likes: 32 },
      { username: 'usuario2', likes: 18 },
    ];
  }, [demo]);

  return (
    <div className="min-h-screen bg-[#1e1e1e] text-[#f5f5f5]">
      {/* Header */}
      <div className="h-[64px] border-b border-white/10">
        <div className="mx-auto flex h-full w-full max-w-[1400px] items-center justify-between px-6">
          <div
            className="text-[22px] font-bold tracking-wide text-[#ff7849]"
            style={{ fontFamily: 'Arimo, Poppins, system-ui' }}
          >
            FitTrack
          </div>

          <nav className="hidden items-center gap-1 md:flex">
            <NavItem active icon={Home} label="Inicio" onClick={() => navigate('/dashboard')} />
            <NavItem icon={CalendarDays} label="Calendario" onClick={() => {}} />
            <NavItem icon={LayoutGrid} label="FitGram" onClick={() => {}} />
            <NavItem icon={Trophy} label="Logros" onClick={() => {}} />
            <NavItem icon={MessageSquareText} label="Chat IA" onClick={() => {}} />
          </nav>

          <button
            type="button"
            onClick={() => {}}
            className="inline-flex items-center gap-2 rounded-lg bg-white/10 px-4 py-2 text-[14px] font-medium text-white/90 transition hover:bg-white/15"
          >
            <UserRound className="h-4 w-4" />
            Perfil
          </button>
        </div>
      </div>

      {/* Layout */}
      <div className="mx-auto grid w-full max-w-[1400px] grid-cols-1 gap-5 px-6 py-6 lg:grid-cols-[1fr_360px]">
        {/* Left */}
        <div className="space-y-5">
          <Card className="p-0">
            <div className="px-5 pt-5">
              <div className="text-[16px] font-semibold tracking-wide text-white/85" style={{ fontFamily: 'Arimo, Poppins, system-ui' }}>
                RESUMEN SEMANAL
              </div>
            </div>

            <div className="mt-4 overflow-x-auto px-5 pb-5">
              <div className="flex gap-2 sm:gap-3 lg:gap-4">
                {weekly.map((d) => {
                  return (
                    <div
                      key={`${d.label}-${d.date}`}
                      className={cx(
                        'flex flex-col rounded-xl border bg-white/[0.04] p-2 sm:p-3 transition-all flex-shrink-0',
                        'w-[90px] h-[110px] sm:w-[100px] sm:h-[120px] lg:w-[110px] lg:h-[130px]',
                        d.isToday ? 'border-white/70 bg-white/[0.08]' : 'border-white/10'
                      )}
                    >
                      <div className="text-[10px] sm:text-[11px] font-semibold uppercase tracking-wide text-white/45">
                        {d.label}
                      </div>
                      <div className="text-[12px] sm:text-[13px] font-medium text-white/60 mt-0.5">
                        {d.date}
                      </div>
                      <div className="mt-2 flex flex-1 flex-col gap-1.5 overflow-hidden">
                        {d.items.length
                          ? d.items.slice(0, 2).map((it) => <Chip key={it}>{it}</Chip>)
                          : null}
                      </div>
                    </div>
                  );
                })}
              </div>
            </div>
          </Card>

          <div className="grid grid-cols-1 gap-5 lg:grid-cols-2">
            <Card className="min-h-[420px]">
              <CardTitle>SESIÓN DE HOY</CardTitle>
              <div className="px-5 pb-5 pt-4">
                {!todayExercises.length ? (
                  <PlusEmpty label="Crear sesión de hoy" />
                ) : (
                  <>
                    <div className="space-y-3">
                      {todayExercises.map((ex) => (
                        <ExerciseRow
                          key={ex.name}
                          name={ex.name}
                          series={ex.series}
                          reps={ex.reps}
                        />
                      ))}
                    </div>

                    <div className="mt-4 flex justify-center">
                      <button
                        type="button"
                        className="inline-flex items-center gap-2 rounded-lg border border-white/15 bg-white/[0.04] px-5 py-2 text-[13px] font-medium text-white/75 transition hover:border-white/25 hover:text-white/90"
                      >
                        <Plus className="h-4 w-4" />
                        Detalle
                      </button>
                    </div>
                  </>
                )}
              </div>
            </Card>

            <Card className="min-h-[420px]">
              <CardTitle>LOGROS</CardTitle>
              <div className="px-5 pb-5 pt-4">
                {!achievements.length ? (
                  <PlusEmpty label="Crear logro" />
                ) : (
                  <div className="space-y-3">
                    {achievements.map((a, i) => (
                      <AchievementRow
                        key={`${a.subtitle}-${i}`}
                        icon={a.icon}
                        title={a.title}
                        subtitle={a.subtitle}
                        meta={a.meta}
                      />
                    ))}
                  </div>
                )}
              </div>
            </Card>
          </div>
        </div>

        {/* Right */}
        <Card className="h-auto min-h-[400px] sm:min-h-[500px] lg:min-h-[720px] overflow-hidden">
          <div className="flex items-center justify-between px-4 sm:px-5 pt-4 sm:pt-5">
            <h2 className="text-[18px] sm:text-[20px] font-bold tracking-wide text-white/90" style={{ fontFamily: 'Arimo, Poppins, system-ui' }}>
              FITGRAM
            </h2>
          </div>

          <div className="px-4 sm:px-5 pb-4 sm:pb-5 pt-3 sm:pt-4 h-full">
            {!fitgram.length ? (
              <div className="flex h-full items-center justify-center min-h-[300px] sm:min-h-[400px] lg:min-h-[600px]">
                <button
                  type="button"
                  className="grid h-12 w-12 place-items-center rounded-full border border-white/20 text-white/70 hover:border-white/30 hover:text-white/90 transition"
                  aria-label="Crear publicación"
                >
                  <Plus className="h-5 w-5" />
                </button>
              </div>
            ) : (
              <div className="space-y-3 sm:space-y-4 max-h-[600px] lg:max-h-[calc(100vh-200px)] overflow-auto pr-1">
                {fitgram.map((p) => (
                  <FitgramPost key={p.username} username={p.username} likes={p.likes} />
                ))}
              </div>
            )}
          </div>
        </Card>
      </div>
    </div>
  );
}
